import "server-only";
import path from "node:path";
import type { Bucket } from "./storage";

const ROOT = path.join(process.cwd(), ".storage");

/** On-disk path of a dev-storage object. Keys are generated by us (folder/year/uuid.ext). */
export function devPath(bucket: Bucket, key: string) {
  const resolved = path.resolve(ROOT, bucket, key);
  if (!resolved.startsWith(path.join(ROOT, bucket) + path.sep)) throw new Error("Invalid key");
  return resolved;
}
